const upsertCourse = `-- name: UpsertCourse :exec
INSERT INTO order_courses (order_id, course, state, fired_at, target_at, target_set, urgent, served_at)
VALUES (?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (order_id, course) DO UPDATE SET state = excluded.state, fired_at = excluded.fired_at,
    target_at = excluded.target_at, target_set = excluded.target_set, urgent = excluded.urgent,
    served_at = excluded.served_at
`

type UpsertCourseParams struct {
	OrderID   string
	Course    string
	State     string
	FiredAt   sql.NullInt64
	TargetAt  sql.NullInt64
	TargetSet int64
	Urgent    int64
	ServedAt  sql.NullInt64
}

func (q *Queries) UpsertCourse(ctx context.Context, arg UpsertCourseParams) error {
	_, err := q.db.ExecContext(ctx, upsertCourse,
		arg.OrderID,
		arg.Course,
		arg.State,
		arg.FiredAt,
		arg.TargetAt,
		arg.TargetSet,
		arg.Urgent,
		arg.ServedAt,
	)
	return err
}
